INSERT OR IGNORE INTO studio_revisions (id,entity_type,entity_id,entity_label,changed_by,changed_by_email,snapshot,created_at) VALUES ('cef536ea-e090-4391-bc59-45b6d6a5624d','studio_characters','eaaf8270-7b8d-4c38-99ee-3ac9d9b1b478','Venny''Claire','db618e68-0656-4b9b-b308-81e071faf745','Bryannaparker2521@gmail.com','{"id":"eaaf8270-7b8d-4c38-99ee-3ac9d9b1b478","name":"Venny''Claire","media":{"tbdFields":"","canonLocks":"Rich warm brown skin\nDeep brown eyes\nBlack 4c hair\nWild untamed hairstyle\nCompact agile build\nNatural linen dress\nBraided leather waist cord\nLayered jewelry\nLeather sandals\nBlack werepanther form\nSilver right hind leg patch","galleryUrl":"","mediaNotes":"Official visual references include the solo human portrait, human production sheet, and black werepanther production sheet.","galleryUrls":[],"portraitUrl":"https://dblwgpiiwkjhdegsindx.supabase.co/storage/v1/object/public/studio-character-media/db618e68-0656-4b9b-b308-81e071faf745/eaaf8270-7b8d-4c38-99ee-3ac9d9b1b478/portrait/1790359991558-venny-claire-character-portrait.png","visualAssets":"Character Portrait — Done\nReference / Production Sheet — Done\nAlternate / True Form — Done","productionNotes":"Maintain the established anime design across future artwork. Human-form references establish her youthful face, warm brown skin, deep brown eyes, wild 4c hair, compact build, linen dress, layered jewelry, braided leather waist cord, and sandals. Werebeast references establish the sleek black werepanther design.","referenceArtUrl":"https://dblwgpiiwkjhdegsindx.supabase.co/storage/v1/object/public/studio-character-media/db618e68-0656-4b9b-b308-81e071faf745/eaaf8270-7b8d-4c38-99ee-3ac9d9b1b478/reference/1790359997049-venny-claire-reference-production-sheet.png","alternateFormUrl":"https://dblwgpiiwkjhdegsindx.supabase.co/storage/v1/object/public/studio-character-media/db618e68-0656-4b9b-b308-81e071faf745/eaaf8270-7b8d-4c38-99ee-3ac9d9b1b478/alternate/1790360002404-venny-claire-alternate-true-form.png"},"status":"complete","user_id":"db618e68-0656-4b9b-b308-81e071faf745","identity":{"age":"","era":"","name":"Venny''Claire","race":"Werebeast","alias":"","gender":"Female","titles":"","subrace":"Werepanther","summary":"Venny''Claire is one of King Kaelo''s children and the mirror counterpart of Venny''Macon. Playful, carefree, and highly curious, she embraces movement and instinct with natural confidence. Her exceptional awareness and agility make her a swift, perceptive presence who treats the world around her as something to explore.","heritage":"Dire Wolf lineage","homeland":"Moonwood Vail","pronouns":"She/Her","birthDate":"","nicknames":"","occupation":"","affiliation":"","apparentAge":"","canonStatus":"Canon","nameMeaning":"","nationality":"","spoilerLevel":"","pronunciation":"","currentResidence":"Moonwood Vail","elementalHeritage":""},"abilities":{"weapons":"","strengths":"Exceptional agility\nHigh speed\nHeightened awareness\nFast reflexes\nFluid movement\nAcrobatic mobility","weaknesses":"","combatStyle":["Agile","Acrobatic","Instinctive","Evasive","Speed-focused"],"limitations":"","powerSource":["Werepanther heritage","Dire Wolf lineage"],"abilityNotes":"Her heightened senses provide a constant low-level stream of sensory information that guides her movements and gives her exceptional awareness of her surroundings.","combatProfile":"Venny''Claire relies on speed, agility, instinct, and constant sensory awareness rather than overwhelming physical force. Her compact werepanther form allows rapid directional changes, fluid evasive movement, and acrobatic attacks.","weaponDetails":"","transformations":"Sudo Form\nBlack Werepanther Form","primaryAbilities":"Werepanther Transformation\nEnhanced Agility\nEnhanced Speed\nHeightened Senses","secondaryAbilities":"Enhanced Awareness\nEnhanced Reflexes\nAcrobatic Movement\nStealth","signatureTechniques":"","transformationDetails":"Venny''Claire''s full werebeast form is a sleek black werepanther with a deep, inky coat that seems to absorb light. Her smaller, compact body is built for speed, stealth, and acrobatic agility. Her only visible dire wolf trait is a silver patch of fur on her right hind leg. She moves with fluid grace and retains her playful curiosity and exceptional awareness."},"is_public":false,"appearance":{"build":["Compact","Lean","Agile"],"nails":"","eyeHex":"","height":"","makeup":"","weight":"","hairHex":"","skinHex":"","eyeColor":["Deep brown"],"grooming":"Natural","skinTone":["Rich warm brown"],"wardrobe":"Sleeveless linen dress\nLeather sandals","hairColor":["Black"],"hairStyle":"Wild and untamed","accessories":"Braided leather waist cord\nLayered necklaces\nBeaded jewelry\nGold earrings\nGold bracelet","faceDetails":["High cheekbones","Small symmetrical nose","Youthful features"],"hairTexture":["4c","Dense"],"colorPalette":"Warm Brown\nBlack\nNatural Linen\nLeather Brown\nGold\nSilver","dominantHand":"","outfitColors":"Natural linen\nLeather brown\nGold","alternateForm":["Black Werepanther","Sudo Form"],"clothingStyle":"Light, practical clothing that allows unrestricted movement and suits the climate of Moonwood Vail.","appearanceNotes":"Venny''Claire closely mirrors Venny''Macon in facial structure, complexion, eyes, and hair. She is smaller and more compact than her brother, with a lighter frame suited to speed, agility, and acrobatic movement.","outfitMaterials":["Woven linen","Leather","Beads","Metal"],"postureMovement":["Relaxed posture","Fluid movement","Light-footed"],"signatureOutfit":"Simple sleeveless woven linen dress secured with a braided leather waist cord and worn with leather sandals.","distinguishingFeatures":["Large wide-set eyes"]},"created_at":"2026-09-25T17:42:10.890987+00:00","updated_at":"2026-09-25T18:13:37.010421+00:00","is_complete":true,"origin_lore":{"fears":"","goals":"","beliefs":"","culture":["Moonwood Vail"],"lineage":"Dire Wolf and Werepanther","storyArc":"","backstory":"","childhood":"","lifestyle":"","storyRole":"Venny''Claire represents instinct, curiosity, and freedom of movement. Her natural confidence and heightened awareness contrast with Venny''Macon''s uncertainty, making the twins mirrors in appearance but opposites in how they approach their abilities.","birthplace":"","psychology":["Highly instinctive","Constantly aware","Lives in the moment"],"motivations":["Exploration","Curiosity"],"personality":["Playful","Carefree","Curious","Unserious","Mischievous","Observant"],"voiceSpeech":"","likesDislikes":"","majorLifeEvents":""},"canon_status":"concept","current_step":6,"portrait_url":"https://dblwgpiiwkjhdegsindx.supabase.co/storage/v1/object/public/studio-character-media/db618e68-0656-4b9b-b308-81e071faf745/eaaf8270-7b8d-4c38-99ee-3ac9d9b1b478/portrait/1790359991558-venny-claire-character-portrait.png","relationships":{"allies":"","rivals":"","enemies":"","mentors":"","parents":"King Kaelo","partner":"","children":"","siblings":"Cosmo\nGemma\nCalliope\nHuxleigh\nPeregrine\nVenny''Macon","worldConnections":"Moonwood Vail","relationshipNotes":"Venny''Claire and Venny''Macon are mirror counterparts in appearance and temperament. Their shared features emphasize their connection, while her playful confidence and instinctive nature contrast with his reserved uncertainty."},"spoiler_level":"private","race_record_id":"a13abf6d-6ff2-42f4-a082-2ab7de1c32d4","realm_record_id":"63782818-208e-4e9b-a57c-9c33daba0589","workflow_status":"draft","family_record_id":"bbe46246-e94b-498d-9ab5-cae88e0804f7","faction_record_id":null}','2026-09-25T18:27:18.723591+00:00');
INSERT OR IGNORE INTO studio_revisions (id,entity_type,entity_id,entity_label,changed_by,changed_by_email,snapshot,created_at) VALUES ('9ae1a17d-ed71-4ede-9bc9-cf0dccd8aedd','studio_characters','37c82673-519e-4ab9-bcea-ed600577eec0','Huxleigh','db618e68-0656-4b9b-b308-81e071faf745','Bryannaparker2521@gmail.com','{"id":"37c82673-519e-4ab9-bcea-ed600577eec0","name":"Huxleigh","media":{"tbdFields":"Pronunciation\nName meaning\nBirth date\nSpoiler level\nHeritage\nNationality\nOccupation\nHeight\nWeight\nDominant hand\nSignature outfit\nAccessories\nChildhood\nMajor life events\nGoals\nFears\nBeliefs\nStory arc\nWeapons\nSignature techniques\nWeaknesses\nLimitations\nPartner\nAllies\nRivals\nEnemies\nMentors","canonLocks":"Male\nMid 20s\nKing Kaelo''s son\nOne of seven children\nMoonwood Vail\nRich dark-brown skin\nAmber eyes\nShort thick 4C hair\nFaded sides\nLarge powerful build\nPolar bear / dire wolf hybrid\nWhite and silver beast fur\nGray beast undertones\nLong dire wolf snout\nControlled rage","galleryUrl":"","mediaNotes":"Existing human and werebeast artwork establishes Huxleigh''s visual identity. Generated image text, weapons, tattoos, abilities, measurements, affiliations, or clothing details not established in written canon should not be treated as canon.","galleryUrls":[],"portraitUrl":"","visualAssets":"Character Portrait — Done\nReference / Production Sheet — Done\nAlternate / True Form — Done\nFull-Body Front — Needed\nBack View — Needed\nLeft View — Needed\nRight View — Needed\nFace Reference — Done\nEye Reference — Done\nHair Reference — Done\nOutfit Breakdown — Needed\nExpression Sheet — Done\nCombat Reference — Needed","productionNotes":"Future artwork must preserve Huxleigh''s established anime/fantasy design. Human artwork should retain his dark-brown skin, amber eyes, short thick 4C curls with faded sides, rugged face, broad shoulders, and dense muscular build. Werebeast artwork must preserve the polar bear scale, dire wolf anatomy, white and silver fur with gray tones, elongated muzzle, and amber eyes.","referenceArtUrl":"","alternateFormUrl":""},"status":"draft","user_id":"db618e68-0656-4b9b-b308-81e071faf745","identity":{"age":"Mid 20s","era":"500–1300 AD-inspired","name":"Huxleigh","race":"Werebeast","alias":"","gender":"Male","titles":"","subrace":"Polar Bear / Dire Wolf Hybrid","summary":"Huxleigh is one of King Kaelo''s seven children and a powerful werebeast of Moonwood Vail. Large, broad-shouldered, and physically imposing, he carries himself with intimidating confidence and controlled strength. His gruff exterior and frequent scowl conceal a mischievous sense of humor. His werebeast form combines the immense scale of a polar bear with the lean musculature and long snout of a dire wolf.","heritage":"","homeland":"Moonwood Vail","pronouns":"He/Him","birthDate":"","nicknames":"","occupation":"","affiliation":"Moonwood Vail Royal Family","apparentAge":"Mid 20s","canonStatus":"Canon","nameMeaning":"","nationality":"","spoilerLevel":"","pronunciation":"","currentResidence":"Moonwood Vail","elementalHeritage":""},"abilities":{"weapons":"","strengths":"Immense physical power\nDense musculature\nControlled brute force\nPhysical intimidation\nStrong self-control","weaknesses":"","combatStyle":["Brute force","Direct attacks","Heavy strikes","Controlled aggression"],"limitations":"","powerSource":["Werebeast physiology"],"abilityNotes":"No elemental magic, cryokinesis, magical weapons, or other supernatural abilities beyond his established werebeast traits have been confirmed.","combatProfile":"Huxleigh fights through overwhelming physical power and direct aggression while maintaining deliberate control. His tremendous weight and strength do not eliminate his grace or precision. His werebeast form greatly emphasizes close-range physical dominance.","weaponDetails":"","transformations":"Polar Bear / Dire Wolf Form","primaryAbilities":"Werebeast Transformation\nEnhanced Strength\nEnhanced Durability","secondaryAbilities":"Enhanced Senses","signatureTechniques":"","transformationDetails":"Huxleigh becomes a monstrous quadrupedal werebeast the size of an enormous polar bear. His form retains a lean, muscular dire wolf structure and long predatory snout beneath thick white, silver, and gray fur. His amber eyes remain prominent. His growl becomes a deep rumble, while his demeanor shifts toward controlled rage and immense brute force restrained by conscious will."},"is_public":false,"appearance":{"build":["Large","Broad-shouldered","Dense","Powerful","Muscular"],"nails":"","eyeHex":["Amber — #D88924"],"height":"","makeup":"","weight":"","hairHex":["Black — #11100F"],"skinHex":["Dark Brown — #4A2B20"],"eyeColor":["Amber"],"grooming":"","skinTone":["Rich dark brown"],"wardrobe":"","hairColor":["Black"],"hairStyle":"Short dense curls with faded sides","accessories":"","faceDetails":["Rugged handsome features","Strong jawline","Straight nose","Deep-set eyes"],"hairTexture":["4C","Thick","Tightly curled"],"colorPalette":"Dark Brown — #4A2B20\nBlack — #11100F\nAmber — #D88924\nPolar White — #EEEDE8\nSilver — #BFC2C5\nWolf Gray — #777A7D","dominantHand":"","outfitColors":"","alternateForm":["Monstrous polar bear scale","Dire wolf physique","Long dire wolf snout","White fur","Silver fur","Gray undertones","Thick matted coat"],"clothingStyle":"","appearanceNotes":"Huxleigh''s human form should emphasize dense physical strength rather than exaggerated bulk. His werebeast form is enormous and quadrupedal, combining polar bear mass with the leaner muscular structure and elongated muzzle of a dire wolf. The hybrid silhouette must clearly communicate both bloodlines.","outfitMaterials":"","postureMovement":["Heavy","Direct","Controlled","Graceful","Self-assured"],"signatureOutfit":"","distinguishingFeatures":["Intimidating scowl","Powerful physique"]},"created_at":"2026-09-25T18:35:44.284815+00:00","updated_at":"2026-09-25T18:35:44.284815+00:00","is_complete":false,"origin_lore":{"fears":"","goals":"","beliefs":"","culture":["Moonwood Vail"],"lineage":"King Kaelo''s bloodline","storyArc":"","backstory":"Huxleigh is one of King Kaelo''s seven children and belongs to the royal family of Moonwood Vail. Further personal history has not yet been established.","childhood":"","lifestyle":"","storyRole":"Huxleigh is a member of King Kaelo''s royal family and one of his seven children. His larger individual role remains unestablished.","birthplace":"Moonwood Vail","psychology":["Controlled aggression","Strong self-control","Hidden playful streak"],"motivations":"","personality":["Self-assured","Confident","Gruff","Intimidating","Controlled","Mischievous"],"voiceSpeech":["Deep","Gruff","Direct"],"likesDislikes":"","majorLifeEvents":""},"canon_status":"concept","current_step":2,"portrait_url":null,"relationships":{"allies":"","rivals":"","enemies":"","mentors":"","parents":"King Kaelo","partner":"","children":"","siblings":"Cosmo\nGemma\nCalliope\nPeregrine\nVenny''Claire\nVenny''Macon","worldConnections":"Moonwood Vail","relationshipNotes":"Huxleigh is one of King Kaelo''s seven children. Individual relationship dynamics with his siblings have not yet been established."},"spoiler_level":"private","race_record_id":"a13abf6d-6ff2-42f4-a082-2ab7de1c32d4","realm_record_id":"63782818-208e-4e9b-a57c-9c33daba0589","workflow_status":"draft","family_record_id":null,"faction_record_id":"ec408c98-c948-442c-9c14-74dd07dde097"}','2026-09-25T18:35:48.079457+00:00');
INSERT OR IGNORE INTO studio_revisions (id,entity_type,entity_id,entity_label,changed_by,changed_by_email,snapshot,created_at) VALUES ('1aa2ea48-b826-4fb6-b4be-21129825b338','studio_characters','3fd4e4a6-bb47-4ed5-9d1f-cae8636d7a3a','Vorlenien "Vorlag" Hochmeister','db618e68-0656-4b9b-b308-81e071faf745','Bryannaparker2521@gmail.com','{"id":"3fd4e4a6-bb47-4ed5-9d1f-cae8636d7a3a","name":"Vorlenien \"Vorlag\" Hochmeister","media":{"tbdFields":"","canonLocks":"Black hair\nPiercing blue eyes\nTall build\nLean-muscular build\nBroad shoulders\nRegal presence","galleryUrl":"","mediaNotes":"","galleryUrls":[],"portraitUrl":"","visualAssets":"Character Portrait — Done","productionNotes":"","referenceArtUrl":"","alternateFormUrl":""},"status":"draft","user_id":"db618e68-0656-4b9b-b308-81e071faf745","identity":{"age":"","era":"","name":"Vorlenien \"Vorlag\" Hochmeister","race":"","alias":"King","gender":"Male","titles":"King of Shadowfen","subrace":"","summary":"King Vorlenien \"Vorlag\" Hochmeister is the ruler of Shadowfen and wielder of the great runic magic inherited through his male bloodline. After his noble family was stripped of its status and later massacred in a fire secretly orchestrated by The Church, his dormant runic power awakened through overwhelming trauma. Raised and manipulated by The Church afterward, Vorlag pursued vengeance, power, and kingship while believing the prophecy surrounding his Runes of Dominion represented his true destiny.","heritage":"","homeland":"","pronouns":"He/Him","birthDate":"","nicknames":"Vorlag","occupation":"King","affiliation":"Shadowfen","apparentAge":"","canonStatus":"Canon","nameMeaning":"","nationality":"","spoilerLevel":"","pronunciation":"","currentResidence":"Shadowfen","elementalHeritage":""},"abilities":{"weapons":"","strengths":"Exceptional intellect\nRunic power\nStrategic planning\nStrong will\nPolitical authority","weaknesses":"Unresolved trauma\nFear of helplessness\nProtective obsession\nSusceptibility to Church manipulation","combatStyle":"","limitations":["Runes were initially uncontrollable"],"powerSource":["Hochmeister bloodline","Great Runic Magic"],"abilityNotes":"The great runic magic passes through the male Hochmeister bloodline. Vorlag''s abilities remained dormant until the destruction of his family triggered their violent awakening at age twelve.","combatProfile":"Vorlag possesses powerful hereditary runic magic awakened through extreme trauma. His Runes of Dominion form the supernatural foundation of his authority and are central to the prophecy cultivated around him by The Church.","weaponDetails":"","transformations":"","primaryAbilities":"Runic Magic\nRunes of Dominion","secondaryAbilities":"","signatureTechniques":"","transformationDetails":""},"is_public":false,"appearance":{"build":["Tall","Lean-muscular","Broad-shouldered"],"nails":"","eyeHex":"","height":"","makeup":"","weight":"","hairHex":"","skinHex":"","eyeColor":["Piercing blue"],"grooming":"","skinTone":["Pale"],"wardrobe":"","hairColor":["Black"],"hairStyle":"","accessories":"","faceDetails":["Sharp jawline","Angular features","Strong brows"],"hairTexture":"","colorPalette":"","dominantHand":"","outfitColors":"","alternateForm":"","clothingStyle":"","appearanceNotes":"","outfitMaterials":"","postureMovement":["Regal","Controlled","Commanding"],"signatureOutfit":"","distinguishingFeatures":""},"created_at":"2026-09-25T18:39:22.116779+00:00","updated_at":"2026-09-25T18:39:22.116779+00:00","is_complete":false,"origin_lore":{"fears":["Losing his family","Powerlessness","Failing to protect Theron","Losing control"],"goals":["Secure Shadowfen","Strengthen his rule","Fulfill his perceived destiny"],"beliefs":["Power ensures protection","Control prevents chaos","His runes mark his destiny","He is destined to rule"],"culture":"","lineage":"Hochmeister noble bloodline","storyArc":"Vorlag''s tragedy begins with a child desperate to protect his family and develops into a ruler who equates safety with absolute control. His vengeance and rise to power appear self-directed, but both were cultivated by The Church. The eventual truth behind his family''s massacre threatens the foundation of his identity, kingship, and belief in his destiny.","backstory":"At twelve, Vorlag returned with Vex, Corvin Sterling, and Alistar Vane to find the Hochmeister home engulfed in flames. Hearing his family trapped inside triggered the violent awakening of his inherited runic magic, forcing Vex to knock him unconscious before the uncontrolled eruption worsened. The massacre had secretly been engineered by The Church to awaken Vorlag''s power and advance a prophecy surrounding the Runes of Dominion. Church agents subsequently sheltered and trained him while directing his vengeance toward the nobles they had used as puppets. Vorlag eventually rose to kingship, married Isolde, established Shadowfen as his seat of power, and extended his influence into Ironspire Hold and the Lionheart Plains while remaining unaware of the full extent of The Church''s manipulation.","childhood":"Vorlag was born into a high-ranking noble family and displayed exceptional intellect from childhood. At age six, rival nobles stripped his family of its position and reduced them to commoners. He witnessed repeated humiliation and abuse directed toward his family and learned that openly resisting their aggressors could bring even greater retaliation.","lifestyle":["Royal governance","Military oversight","Runic training"],"storyRole":"Vorlag serves as the tyrannical King of Shadowfen while unknowingly remaining a central piece in The Church''s long-term plan. His rule, runic inheritance, and manipulated prophecy connect him to the artifact that Elias Thorne will eventually seek to protect.","birthplace":"","psychology":["Deep fear of helplessness","Obsessed with control","Protection through power","Unresolved family grief","Trauma-driven vigilance","Righteous self-justification"],"motivations":["Protect his family","Prevent future helplessness","Maintain absolute control","Fulfill the Dominion prophecy","Preserve Shadowfen"],"personality":["Intelligent","Calculating","Protective","Driven","Controlling","Ruthless","Traumatized","Determined","Suspicious"],"voiceSpeech":["Commanding","Controlled","Authoritative"],"likesDislikes":"","majorLifeEvents":"Born into House Hochmeister\nFamily stripped of noble status\nFamily reduced to commoners\nWitnessed repeated family abuse\nAttempted to defend his family\nHochmeister home burned\nFamily killed in the fire\nRunic magic awakened\nTaken in by The Church\nTrained by The Church\nHunted the responsible nobles\nFalsely accused of killing his family\nPursued the Dominion prophecy\nMarried Isolde\nBecame King\nEstablished Shadowfen"},"canon_status":"concept","current_step":2,"portrait_url":null,"relationships":{"allies":"Count Vex\nLord Corvin Sterling\nLord Alistar Vane","rivals":"","enemies":"","mentors":"","parents":"","partner":"Isolde","children":"Theron","siblings":"","worldConnections":"Shadowfen\nIronspire Hold\nLionheart Plains","relationshipNotes":"Vex, Corvin Sterling, and Alistar Vane were Vorlag''s closest childhood friends and remained central figures in his rise. Vex helped keep him level-headed through cynical distraction, Corvin brought humor during their childhood, and Alistar provided intellectual and physical motivation. The Church later positioned itself as Vorlag''s benefactor while secretly having engineered the destruction of his family."},"spoiler_level":"private","race_record_id":null,"realm_record_id":null,"workflow_status":"draft","family_record_id":null,"faction_record_id":"74fb0163-f452-4f7e-a9ea-13c15bb960db"}','2026-09-25T18:39:28.418552+00:00');
