INSERT OR IGNORE INTO studio_revisions (id,entity_type,entity_id,entity_label,changed_by,changed_by_email,snapshot,created_at) VALUES ('9a247eb3-ae57-4c8c-af4e-931d413c69d0','studio_characters','37c82673-519e-4ab9-bcea-ed600577eec0','Huxleigh','db618e68-0656-4b9b-b308-81e071faf745','Bryannaparker2521@gmail.com','{"id":"37c82673-519e-4ab9-bcea-ed600577eec0","name":"Huxleigh","media":{"tbdFields":"Pronunciation\nName meaning\nBirth date\nSpoiler level\nHeritage\nNationality\nOccupation\nHeight\nWeight\nDominant hand\nSignature outfit\nAccessories\nChildhood\nMajor life events\nGoals\nFears\nBeliefs\nStory arc\nWeapons\nSignature techniques\nWeaknesses\nLimitations\nPartner\nAllies\nRivals\nEnemies\nMentors","canonLocks":"Male\nMid 20s\nKing Kaelo''s son\nOne of seven children\nMoonwood Vail\nRich dark-brown skin\nAmber eyes\nShort thick 4C hair\nFaded sides\nLarge powerful build\nPolar bear / dire wolf hybrid\nWhite and silver beast fur\nGray beast undertones\nLong dire wolf snout\nControlled rage","galleryUrl":"","mediaNotes":"Existing human and werebeast artwork establishes Huxleigh''s visual identity. Generated image text, weapons, tattoos, abilities, measurements, affiliations, or clothing details not established in written canon should not be treated as canon.","galleryUrls":[],"portraitUrl":"","visualAssets":"Character Portrait — Done\nReference / Production Sheet — Done\nAlternate / True Form — Done\nFull-Body Front — Needed\nBack View — Needed\nLeft View — Needed\nRight View — Needed\nFace Reference — Done\nEye Reference — Done\nHair Reference — Done\nOutfit Breakdown — Needed\nExpression Sheet — Done\nCombat Reference — Needed","productionNotes":"Future artwork must preserve Huxleigh''s established anime/fantasy design. Human artwork should retain his dark-brown skin, amber eyes, short thick 4C curls with faded sides, rugged face, broad shoulders, and dense muscular build. Werebeast artwork must preserve the polar bear scale, dire wolf anatomy, white and silver fur with gray tones, elongated muzzle, and amber eyes.","referenceArtUrl":"","alternateFormUrl":""},"status":"complete","user_id":"db618e68-0656-4b9b-b308-81e071faf745","identity":{"age":"Mid 20s","era":"500–1300 AD-inspired","name":"Huxleigh","race":"Werebeast","alias":"","gender":"Male","titles":"","subrace":"Polar Bear / Dire Wolf Hybrid","summary":"Huxleigh is one of King Kaelo''s seven children and a powerful werebeast of Moonwood Vail. Large, broad-shouldered, and physically imposing, he carries himself with intimidating confidence and controlled strength. His gruff exterior and frequent scowl conceal a mischievous sense of humor. His werebeast form combines the immense scale of a polar bear with the lean musculature and long snout of a dire wolf.","heritage":"","homeland":"Moonwood Vail","pronouns":"He/Him","birthDate":"","nicknames":"","occupation":"","affiliation":"Moonwood Vail Royal Family","apparentAge":"Mid 20s","canonStatus":"Canon","nameMeaning":"","nationality":"","spoilerLevel":"","pronunciation":"","currentResidence":"Moonwood Vail","elementalHeritage":""},"abilities":{"weapons":"","strengths":"Immense physical power\nDense musculature\nControlled brute force\nPhysical intimidation\nStrong self-control","weaknesses":"","combatStyle":["Brute force","Direct attacks","Heavy strikes","Controlled aggression"],"limitations":"","powerSource":["Werebeast physiology"],"abilityNotes":"No elemental magic, cryokinesis, magical weapons, or other supernatural abilities beyond his established werebeast traits have been confirmed.","combatProfile":"Huxleigh fights through overwhelming physical power and direct aggression while maintaining deliberate control. His tremendous weight and strength do not eliminate his grace or precision. His werebeast form greatly emphasizes close-range physical dominance.","weaponDetails":"","transformations":"Polar Bear / Dire Wolf Form","primaryAbilities":"Werebeast Transformation\nEnhanced Strength\nEnhanced Durability","secondaryAbilities":"Enhanced Senses","signatureTechniques":"","transformationDetails":"Huxleigh becomes a monstrous quadrupedal werebeast the size of an enormous polar bear. His form retains a lean, muscular dire wolf structure and long predatory snout beneath thick white, silver, and gray fur. His amber eyes remain prominent. His growl becomes a deep rumble, while his demeanor shifts toward controlled rage and immense brute force restrained by conscious will."},"is_public":false,"appearance":{"build":["Large","Broad-shouldered","Dense","Powerful","Muscular"],"nails":"","eyeHex":["Amber — #D88924"],"height":"","makeup":"","weight":"","hairHex":["Black — #11100F"],"skinHex":["Dark Brown — #4A2B20"],"eyeColor":["Amber"],"grooming":"","skinTone":["Rich dark brown"],"wardrobe":"","hairColor":["Black"],"hairStyle":"Short dense curls with faded sides","accessories":"","faceDetails":["Rugged handsome features","Strong jawline","Straight nose","Deep-set eyes"],"hairTexture":["4C","Thick","Tightly curled"],"colorPalette":"Dark Brown — #4A2B20\nBlack — #11100F\nAmber — #D88924\nPolar White — #EEEDE8\nSilver — #BFC2C5\nWolf Gray — #777A7D","dominantHand":"","outfitColors":"","alternateForm":["Monstrous polar bear scale","Dire wolf physique","Long dire wolf snout","White fur","Silver fur","Gray undertones","Thick matted coat"],"clothingStyle":"","appearanceNotes":"Huxleigh''s human form should emphasize dense physical strength rather than exaggerated bulk. His werebeast form is enormous and quadrupedal, combining polar bear mass with the leaner muscular structure and elongated muzzle of a dire wolf. The hybrid silhouette must clearly communicate both bloodlines.","outfitMaterials":"","postureMovement":["Heavy","Direct","Controlled","Graceful","Self-assured"],"signatureOutfit":"","distinguishingFeatures":["Intimidating scowl","Powerful physique"]},"created_at":"2026-09-25T18:35:44.284815+00:00","updated_at":"2026-09-25T18:35:48.079457+00:00","is_complete":true,"origin_lore":{"fears":"","goals":"","beliefs":"","culture":["Moonwood Vail"],"lineage":"King Kaelo''s bloodline","storyArc":"","backstory":"Huxleigh is one of King Kaelo''s seven children and belongs to the royal family of Moonwood Vail. Further personal history has not yet been established.","childhood":"","lifestyle":"","storyRole":"Huxleigh is a member of King Kaelo''s royal family and one of his seven children. His larger individual role remains unestablished.","birthplace":"Moonwood Vail","psychology":["Controlled aggression","Strong self-control","Hidden playful streak"],"motivations":"","personality":["Self-assured","Confident","Gruff","Intimidating","Controlled","Mischievous"],"voiceSpeech":["Deep","Gruff","Direct"],"likesDislikes":"","majorLifeEvents":""},"canon_status":"concept","current_step":6,"portrait_url":null,"relationships":{"allies":"","rivals":"","enemies":"","mentors":"","parents":"King Kaelo","partner":"","children":"","siblings":"Cosmo\nGemma\nCalliope\nPeregrine\nVenny''Claire\nVenny''Macon","worldConnections":"Moonwood Vail","relationshipNotes":"Huxleigh is one of King Kaelo''s seven children. Individual relationship dynamics with his siblings have not yet been established."},"spoiler_level":"private","race_record_id":"a13abf6d-6ff2-42f4-a082-2ab7de1c32d4","realm_record_id":"63782818-208e-4e9b-a57c-9c33daba0589","workflow_status":"draft","family_record_id":"54d24391-3ed4-445b-8bfe-8dba238fc8e0","faction_record_id":"ec408c98-c948-442c-9c14-74dd07dde097"}','2026-09-25T19:18:48.059396+00:00');
